/* Per-part holds generated by matched native-grid reviews. Shared by both renderers. */
const ProtectedLOD = (() => {
  const names = typeof TargetSelectors === 'undefined' ? require('./target-selectors.js') : TargetSelectors;
  const transitions = Object.freeze(['card', 'strand', 'relief-normal', 'relief-painted']);
  const format = 'ink-studio/protected-lod-guard';
  const key = (object, part, transition) => JSON.stringify([object, part ?? null, transition]);
  const compiled = new WeakSet();
  const cache = new WeakMap();

  function prepare(guard) {
    if (guard === undefined || guard === false) return;
    if (compiled.has(guard)) return guard;
    if (cache.has(guard)) return cache.get(guard);
    if (guard?.format !== format || guard.version !== 1 || !Array.isArray(guard.holds) || guard.holds.length > 512)
      throw new TypeError('Expected a version 1 protected LOD guard with up to 512 holds');
    const holds = new Map();
    for (const hold of guard.holds) {
      if (!names.name(hold?.object) || !(hold.part === null || names.name(hold.part)) ||
          !transitions.includes(hold.transition) || !Array.isArray(hold.features) ||
          !hold.features.length || hold.features.length > 128 || !Array.from(hold.features).every(names.name))
        throw new TypeError('Invalid protected LOD hold');
      const id = key(hold.object, hold.part, hold.transition);
      if (holds.has(id)) throw new RangeError('Duplicate protected LOD hold for ' + id);
      holds.set(id, Object.freeze([...new Set(hold.features)]));
    }
    const result = Object.freeze({ features: (object, part, transition) => holds.get(key(object, part, transition)) });
    compiled.add(result);
    cache.set(guard, result);
    return result;
  }

  const active = (world, setting) => prepare(setting ?? world.protectedLOD);
  return Object.freeze({ format, transitions, prepare, active });
})();
if (typeof module !== 'undefined') module.exports = ProtectedLOD;
